from pptx import Presentation

p = "/Users/lisun/workplace/go-harness/web/sessions/session-23/workspace/季度业务汇报.pptx"
prs = Presentation(p)
print("Slide count:", len(prs.slides))
for i, slide in enumerate(prs.slides, 1):
    texts = []
    charts = 0
    tables = 0
    for sh in slide.shapes:
        if sh.has_text_frame and sh.text_frame.text.strip():
            texts.append(sh.text_frame.text.replace("\n"," / ")[:40])
        if sh.has_chart:
            charts += 1
        if sh.has_table:
            tables += 1
    print(f"\n--- 第{i}页 (图表:{charts}, 表格:{tables}) ---")
    for t in texts:
        print("  ", t)

